'use strict';

// Parse a compact duration like "1h30m", "45m", "90s" into seconds.
const UNIT_SECONDS = { h: 3600, m: 60, s: 1 };

function parseDuration(text) {
  let total = 0;
  const components = /(\d+)([hms])/g;
  let match;
  while ((match = components.exec(String(text).trim()))) {
    total += Number(match[1]) * UNIT_SECONDS[match[2]];
  }
  if (total === 0) throw new Error(`bad duration: ${text}`);
  return total;
}

module.exports = { parseDuration };
